65	private parseStructDef(): AST.StructDef {
66	  const startToken = this.consume(TokenType.STRUCT, 'struct 키워드 필수');
67	  const nameToken = this.consume(TokenType.IDENTIFIER, '구조체 이름 필수');
68	  this.consume(TokenType.LBRACE, '{' 필수);
69	
70	  const fields: AST.StructField[] = [];
71	  while (this.peek().type !== TokenType.RBRACE) {
72	    const fieldName = this.consume(TokenType.IDENTIFIER, '필드명 필수').value;
73	    this.consume(TokenType.COLON, ':' 필수);
74	    const typeAnnotation = this.consume(TokenType.IDENTIFIER, '타입 필수').value;
75	    fields.push({ name: fieldName, typeAnnotation, line: ..., column: ... });
76	
77	    if (this.peek().type !== TokenType.RBRACE) {
78	      this.consume(TokenType.COMMA, '쉼표 또는 }' 필수);
79	    }
80	  }
81	  this.consume(TokenType.RBRACE, '}' 필수);
82	  return { type: 'StructDef', name: nameToken.value, fields, ... };
83	}
84	
85	private parseStructLiteral(name: string): AST.StructLiteral {
86	  // Person { name: "Alice", age: 30 }
87	  this.consume(TokenType.LBRACE, '{' 필수);
88	  const fields: Record<string, Expression> = {};
89	
90	  while (this.peek().type !== TokenType.RBRACE) {
91	    const fieldName = this.consume(TokenType.IDENTIFIER, '필드명').value;
92	    this.consume(TokenType.COLON, ':' 필수);
93	    fields[fieldName] = this.parseExpression();
94	
95	    if (this.peek().type !== TokenType.RBRACE) {
96	      this.consume(TokenType.COMMA, '쉼표 또는 }');
97	    }
98	  }
99	  this.consume(TokenType.RBRACE, '}' 필수);
100	  return { type: 'StructLiteral', name, fields, ... };
101	}
102	```
