115	private genVStructDef(def: AST.StructDef): string {
116	  let code = `typedef struct {\n`;
117	  for (const field of def.fields) {
118	    const cType = this.mapTypeToCType(field.typeAnnotation);
119	    code += `  ${cType} ${field.name};\n`;
120	  }
121	  code += `} ${def.name};\n`;
122	  return code;
123	}
