125	case 'StructLiteral':
126	  return this.genVStructLiteral(expr as AST.StructLiteral);
127	
128	private genVStructLiteral(lit: AST.StructLiteral): string {
129	  let code = `(${lit.name}){\n`;
130	  for (const [fieldName, fieldExpr] of Object.entries(lit.fields)) {
131	    code += `  .${fieldName} = ${this.genVExpression(fieldExpr)},\n`;
132	  }
133	  code += `}`;
134	  return code;
135	}
136	```
