140	private genPyStructDef(def: AST.StructDef): string {
141	  let code = `class ${def.name}:\n`;
142	  code += `  def __init__(self`;
143	  for (const field of def.fields) {
144	    code += `, ${field.name}`;
145	  }
146	  code += `):\n`;
147	  for (const field of def.fields) {
148	    code += `    self.${field.name} = ${field.name}\n`;
149	  }
150	  return code;
151	}
152	
153	private genPyStructLiteral(lit: AST.StructLiteral): string {
154	  let args = [];
155	  for (const [fieldName, fieldExpr] of Object.entries(lit.fields)) {
156	    args.push(`${fieldName}=${this.genPyExpression(fieldExpr)}`);
157	  }
158	  return `${lit.name}(${args.join(', ')})`;
159	}
