257	#### 3. `src/nexus/codegen/nexus-codegen.ts`
258	**전략:** 제네릭을 "템플릿 인스턴스화"로 처리
259	
260	```typescript
261	private genVFunctionWithGenerics(fn: AST.VFunction): string {
262	  // 제네릭 없으면 일반 함수 생성
263	  if (!fn.typeParams || fn.typeParams.length === 0) {
264	    return this.genVFunction(fn);
265	  }
266	
267	  // 제네릭 함수: 함수 호출 사이트에서 타입 추론 후 인스턴스화
268	  // 예: first<i64>(arr) → first_i64(arr)
269	  // 이 단계에서는 제네릭 함수를 "템플릿" 주석으로 표시
270	
271	  let code = `// Generic function template\n`;
272	  code += `// ${fn.name}<${fn.typeParams.join(', ')}>\n`;
273	  code += this.genVFunction(fn);
274	  return code;
275	}
276	```
