278	**런타임 인스턴스화 (간단 버전):**
279	```typescript
280	// 함수 호출 시 타입 추론
281	private inferTypeFromCall(callExpr: AST.CallExpr, fn: AST.VFunction): Record<string, string> {
282	  const typeMap: Record<string, string> = {};
283	
284	  for (let i = 0; i < fn.params.length; i++) {
285	    const param = fn.params[i];
286	    const arg = callExpr.args[i];
287	
288	    if (param.isGeneric && param.typeAnnotation?.startsWith('[')) {
289	      // [T] 형식: arg가 배열이면 T = 배열 원소 타입
290	      if (arg.type === 'Array') {
291	        const elemType = this.inferExpressionType(arg as ArrayLiteral);
292	        const typeVar = param.typeAnnotation.slice(1, -1);  // [T] → T
293	        typeMap[typeVar] = elemType;
294	      }
295	    }
296	  }
297	
298	  return typeMap;
299	}
300	```
