366	#### 2. `src/nexus/parser/nexus-parser.ts`
367	**추가:**
368	
369	```typescript
370	private parseMatchStatement(): AST.MatchStatement {
371	  this.consume(TokenType.MATCH, 'match 키워드');
372	  const expr = this.parseExpression();
373	  this.consume(TokenType.LBRACE, '{');
374	
375	  const cases: AST.MatchCase[] = [];
376	  while (this.peek().type !== TokenType.RBRACE) {
377	    const pattern = this.parsePattern();
378	    this.consume(TokenType.ARROW, '=>');
379	    const body = this.parseStatement();  // 단일 statement
380	    cases.push({ pattern, body: [body], line: ..., column: ... });
381	
382	    if (this.peek().type === TokenType.COMMA) {
383	      this.advance();
384	    }
385	  }
386	  this.consume(TokenType.RBRACE, '}');
387	
388	  return { type: 'MatchStatement', expr, cases, ... };
389	}
390	
391	private parsePattern(): AST.Pattern {
392	  const token = this.peek();
393	
394	  if (token.type === TokenType.IDENTIFIER && token.value === '_') {
395	    this.advance();
396	    return { type: 'Wildcard' };
397	  }
398	
399	  if (token.type === TokenType.NUMBER) {
400	    const value = this.advance().value;
401	
402	    // Range: 1..10
403	    if (this.peek().type === TokenType.DOT && this.peek(1).type === TokenType.DOT) {
404	      this.advance();
405	      this.advance();
406	      const end = this.consume(TokenType.NUMBER, '숫자').value;
407	      return { type: 'Range', start: Number(value), end: Number(end) };
408	    }
409	
410	    return { type: 'Literal', value: Number(value) };
411	  }
412	
413	  if (token.type === TokenType.STRING) {
414	    const value = this.advance().value;
415	    return { type: 'Literal', value };
416	  }
417	
418	  throw new Error(`Unexpected pattern: ${token.type}`);
419	}
420	```
