422	#### 3. `src/nexus/codegen/nexus-codegen.ts`
423	**V 모드:**
424	
425	```typescript
426	case 'MatchStatement':
427	  return this.genVMatchStatement(stmt as AST.MatchStatement);
428	
429	private genVMatchStatement(match: AST.MatchStatement): string {
430	  let code = '';
431	  const exprCode = this.genVExpression(match.expr);
432	
433	  let isFirst = true;
434	  for (const c of match.cases) {
435	    if (isFirst) {
436	      code += `if (`;
437	      isFirst = false;
438	    } else {
439	      code += ` else if (`;
440	    }
441	
442	    code += this.genPatternCondition(exprCode, c.pattern);
443	    code += `) {\n`;
444	    code += this.genVStatements(c.body, '  ');
445	    code += `}`;
446	  }
447	  code += `\n`;
448	
449	  return code;
450	}
451	
452	private genPatternCondition(exprCode: string, pattern: AST.Pattern): string {
453	  if (pattern.type === 'Literal') {
454	    return `${exprCode} == ${pattern.value}`;
455	  } else if (pattern.type === 'Range') {
456	    return `${exprCode} >= ${pattern.start} && ${exprCode} <= ${pattern.end}`;
457	  } else if (pattern.type === 'Wildcard') {
458	    return `1`;  // 항상 참
459	  }
460	  return '';
461	}
462	```
